return ['domain'=>'press-permit-core','plural-forms'=>'nplurals=1; plural=0;','language'=>'ko_KR','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions는 게시물, 페이지, 카테고리, 태그 등에 대한 접근을 허용하거나 거부할 수 있게 해줍니다.','PublishPress'=>'퍼블리시프레스','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'모든 게시물 유형에 대한 태그 편집','Edit Tag for Posts'=>'게시물에 대한 태그 편집','Advanced Custom Fields'=>'고급 사용자 정의 필드','Control front-end access to Field Groups with advanced permission management.'=>'고급 권한 관리를 통해 필드 그룹에 대한 프론트 엔드 접근을 제어합니다.','Control access to Field Groups'=>'필드 그룹에 대한 접근 제어','Front-end visibility restrictions'=>'프런트엔드 가시성 제한','Integration with permission groups'=>'권한 그룹과의 통합','Beaver Builder'=>'비버 빌더','Compatibility with Edit Permissions in Beaver Builder.'=>'비버 빌더에서 편집 권한과의 호환성.','Beaver editor integration'=>'비버 편집기 통합','Widget-level permission controls'=>'위젯 수준의 권한 제어','Template access restrictions'=>'템플릿 접근 제한','bbPress Forums'=>'bbPress 포럼','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'포럼 접근 및 참여에 대한 세부 제어가 가능한 bbPress 전용 권한입니다.','Forum-specific permissions'=>'포럼 전용 권한','Topic creation restrictions'=>'주제 생성 제한','Forum access controls'=>'포럼 접근 제어','BuddyPress'=>'버디프레스','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'BuddyPress 그룹에 게시물 및 용어 권한을 할당하여 콘텐츠 제어를 향상시킵니다.','Assign post permissions to BuddyPress groups'=>'버디프레스 그룹에 게시물 권한 할당','Assign term permissions to BuddyPress groups'=>'버디프레스 그룹에 용어 권한 할당','Group-based content permissions'=>'그룹 기반 